#include <iostream>
#include <vector>
#include <chrono>

// Node structure for BST
struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Function to insert a value into the BST
Node* insert(Node* root, int value) {
    if (root == nullptr) {
        return new Node(value);
    }
    if (value < root->data) {
        root->left = insert(root->left, value);
    } else {
        root->right = insert(root->right, value);
    }
    return root;
}

// Function to perform selection sort
void selectionSort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; ++i) {
        int minIndex = i;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }
        std::swap(arr[i], arr[minIndex]);
    }
}

// Function to create BST from sorted array
Node* createBSTFromSortedArray(const std::vector<int>& arr) {
    Node* root = nullptr;
    for (int value : arr) {
        root = insert(root, value);
    }
    return root;
}

// Function to print BST in inorder traversal
void inorderTraversal(Node* root) {
    if (root != nullptr) {
        inorderTraversal(root->left);
        std::cout << root->data << " ";
        inorderTraversal(root->right);
    }
}

int main() {
    std::vector<int> arr = {10, 5, 15, 2, 7, 12, 18};

    // Measure the time taken for selection sort
    auto start = std::chrono::high_resolution_clock::now();
    selectionSort(arr);
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    std::cout << "Time taken for selection sort: " << duration.count() << " microseconds" << std::endl;

    // Create BST from sorted array
    Node* root = createBSTFromSortedArray(arr);

    // Measure the time taken for creating BST
    start = std::chrono::high_resolution_clock::now();
    end = std::chrono::high_resolution_clock::now();
    duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    std::cout << "Time taken for creating BST: " << duration.count() << " microseconds" << std::endl;

    // Print the BST in inorder traversal
    std::cout << "Inorder traversal of the BST: ";
